function pressed(name){if(name==='left')return isDown('ArrowLeft')||isDown('KeyA')||touch.left;if(name==='right')return isDown('ArrowRight')||isDown('KeyD')||touch.right;if(name==='slow')return isDown('KeyK')||touch.slow;return false}
