for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy+=220*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);for(const s of slashes)s.life-=dt;slashes=slashes.filter(s=>s.life>0);shake=Math.max(0,shake-dt*28);flash=Math.max(0,flash-dt);if(player.hp<=0)finish(false);if(player.x>worldLength-200)finish(true)}

